#include <stdio.h>
#include <string.h>
#include <ctype.h>

char main_out[1024];

int main(int argc, char *argv[]) {
    if (argc < 2) {
        puts("EMPTY");
        return 0;
    }

    char *input = argv[1];
    size_t len = strlen(input);

    if (len > 1024) {
        len = 1024;
    }

    // Find first non-whitespace character
    size_t start = 0;
    while (start < len && (input[start] == ' ' || input[start] == '\t' || 
                           input[start] == '\n' || input[start] == '\r' || 
                           input[start] == '\v' || input[start] == '\f')) {
        start++;
    }

    // If all whitespace, output EMPTY
    if (start == len) {
        puts("EMPTY");
        return 0;
    }

    // Find last non-whitespace character
    size_t end = len - 1;
    while (end > start && (input[end] == ' ' || input[end] == '\t' || 
                           input[end] == '\n' || input[end] == '\r' || 
                           input[end] == '\v' || input[end] == '\f')) {
        end--;
    }

    // Copy trimmed string to output buffer
    size_t out_idx = 0;
    for (size_t i = start; i <= end; i++) {
        main_out[out_idx++] = input[i];
    }
    main_out[out_idx] = '\0';

    puts(main_out);
    return 0;
}
